local config = {
  ui_story_30610601_1_dialog_content = "Oh? Eh, hai.",
  ui_story_30610601_2_dialog_content = "Ya.",
  ui_story_30610601_3_dialog_content = "Maaf mengganggu… A-aku tak mengganggu waktu istirahatmu, 'kan?",
  ui_story_30610601_4_dialog_content = "Sama sekali tidak! Ini juga bagian dari pekerjaanku. Tak usah merasa tak enak hati.",
  ui_story_30610601_5_dialog_content = "Tak enak rasanya kalau kita dikendalikan emosi. Aku sangat paham!",
  ui_story_30610601_6_dialog_content = "Kecemasan, ketidakstabilan, rasa takut akan hal-hal yang tak diketahui, penyesalan atas pilihan kita sendiri…",
  ui_story_30610601_7_dialog_content = "Emosi negatif seperti ini bisa menumpuk seiring waktu dan membuat kita kewalahan. Iya, 'kan?",
  ui_story_30610601_8_dialog_content = "Hmm… Ya, kadang-kadang.",
  ui_story_30610601_9_dialog_content = "Dulu, aku harus mengatasi segala emosi itu seorang diri.",
  ui_story_30610601_10_dialog_content = "Namun, setelah menghabiskan waktu dengan membaca di kamarku, atau tidur nyenyak sepanjang malam…",
  ui_story_30610601_11_dialog_content = "Suasana hatiku biasanya akan membaik dan keesokan harinya aku akan kembali seperti biasa.",
  ui_story_30610601_12_dialog_content = "Hanya saja… Hari ini, aku tak punya banyak waktu untuk menghadapi pikiran dan perasaanku.",
  ui_story_30610601_13_dialog_content = "Beberapa waktu lalu, aku berjanji akan mengunjungi Shadowlord, jadi aku tak punya pilihan selain pergi mengunjunginya hari ini.",
  ui_story_30610601_14_dialog_content = "Akan tetapi, kalau harus menemuinya padahal aku sedang sangat frustrasi begini… Kurasa itu tak sopan.",
  ui_story_30610601_15_dialog_content = "Sepertinya belakangan ini kau mengalami banyak tekanan, PlayerName…",
  ui_story_30610601_16_dialog_content = "Jangan khawatir.",
  ui_story_30610601_17_dialog_content = "Stres dan emosi negatif lainnya memang sulit dijelaskan, tapi tugasku memang membantu orang-orang mencari jalan keluar.",
  ui_story_30610601_18_dialog_content = "Bagaimana kalau kita coba latihan <color=#FFB400>berpikir positif</color> saja?",
  ui_story_30610601_19_dialog_content = "Latihan kognitif semacam ini sudah terbukti bisa membantu agar pikiran depresif dan kecemasan tak makin menguasai pikiran kita.",
  ui_story_30610601_20_dialog_content = "Aku akan memberimu rangsangan acak, misalnya kata-kata, cahaya, atau suara lain, dan berusaha menumbuhkan pikiran positif dan bahagia dalam pikiranmu!",
  ui_story_30610601_21_dialog_content = "Kau hanya perlu duduk tegak dan tenang, lalu pejamkan matamu…",
  ui_story_30610601_22_dialog_content = "Bayangkan dirimu berada di suatu tempat yang tenang dan damai…",
  ui_story_30610601_23_dialog_content = "Kosongkan seluruh pikiranmu… Biarkan pikiran dan emosimu terpencar dan melayang jauh ke tempat lain…",
  ui_story_30610601_24_dialog_content = "Oke.",
  ui_story_30610601_25_dialog_content = "Nah, sekarang… Kita mulai latihannya.",
  ui_story_30610601_26_dialog_content = "Sekarang, aku akan memainkan musik yang menenangkan. Sementara itu, kau terus bayangkan saja hal-hal yang ringan dan menyenangkan.",
  ui_story_30610601_27_dialog_content = "\"Jamur misterius tiba-tiba saja muncul di Gannon City. Dalam semalam saja, sepertinya ada seorang pencuri yang berhasil membersihkan seluruh kota dari hama jamur itu!\"",
  ui_story_30610601_28_dialog_content = "…?",
  ui_story_30610601_29_dialog_content = "\"Saksi di kota Bath menyatakan mereka melihat banyak sekali balon udara melayang di langit pagi ini.",
  ui_story_30610601_30_dialog_content = "…!",
  ui_story_30610601_31_dialog_content = "Uups, maaf… Aku keliru memutar rekaman berita terkini dari Illumina Federation!",
  ui_story_30610601_32_dialog_content = "Maafkan aku, PlayerName! S-sebentar, biar kucari musik yang cocok!",
  ui_story_30610601_33_dialog_content = "… Hah? Tak apa, Chandra. Sebenarnya aku malah senang menyimak rekaman berita itu.",
  ui_story_30610601_34_dialog_content = "Aku membayangkan diriku terbang naik balon udara, perlahan melayang di atas kota Bath…",
  ui_story_30610601_35_dialog_content = "Aku bisa melihat kota dari atas, sementara tiupan angin lembut membawa kita melayang melintasi langit…",
  ui_story_30610601_36_dialog_content = "Rasanya… Cukup menyenangkan.",
  ui_story_30610601_37_dialog_content = "Ah… Begitukah?",
  ui_story_30610601_38_dialog_content = "Bagus! Kalau kau merasa senang dengan membayangkan balon udara, untuk sementara ini kita akan bayangkan balon udara saja, ya.",
  ui_story_30610601_39_dialog_content = "Tentu.",
  ui_story_30610601_40_dialog_content = "Nah, kalau begitu… Kita sedang duduk di dalam balon udara, perlahan membubung makin tinggi ke langit… Di bawah sana, bumi tampak makin kecil di kejauhan…",
  ui_story_30610601_41_dialog_content = "Rumah, hewan, ladang… Semua yang ada di kota makin lama tampak makin kecil dan jauh…",
  ui_story_30610601_42_dialog_content = "Hingga akhirnya, satu-satunya yang bisa kita lihat…",
  ui_story_30610601_43_dialog_content = "Hanyalah birunya langit dan laut.",
  ui_story_30610601_44_dialog_content = "Hoi! PlayerName!",
  ui_story_30610601_45_dialog_content = "Terima kasih sudah memilih Hot-air Ballon Tour Chandra untuk tamasya hari ini!",
  ui_story_30610601_46_dialog_content = "Ch-Chandra, pakaianmu…",
  ui_story_30610601_47_dialog_content = "Hmm? Apa pakaianku membuatmu berubah pikiran?",
  ui_story_30610601_48_dialog_content = "Y-ya, pakaianmu tampak seperti setelan khas komentator…",
  ui_story_30610601_49_dialog_content = "Hmm… Baiklah!",
  ui_story_30610601_50_dialog_content = "Rupanya aku juga cocok melakukan hal lain selain riset!",
  ui_story_30610601_51_option_content = "Pakaiannya sangat cocok untukmu!",
  ui_story_30610601_52_dialog_content = "Sungguh? Hihi, trims!",
  ui_story_30610601_53_dialog_content = "Wow… Menarik!",
  ui_story_30610601_54_dialog_content = "Kebahagiaan yang dirasakan setelah menerima pujian atas penampilan kita… Sungguh suatu emosi yang tak bisa dijelaskan!",
  ui_story_30610601_55_option_content = "Cocok sekali denganmu!",
  ui_story_30610601_56_dialog_content = "Terima kasih banyak!",
  ui_story_30610601_57_dialog_content = "Tahu tidak? Tak banyak orang yang mengomentariku di luar hal terkait pekerjaanku.",
  ui_story_30610601_58_dialog_content = "Seringnya, orang-orang hanya mengomentari bahwa aku sangat banyak membantu mereka, atau bahwa dukungan emosi dariku sangat bermanfaat…",
  ui_story_30610601_59_dialog_content = "A-aku hanya menyampaikan pikiranku, kok! Jangan sungkan…",
  ui_story_30610601_60_dialog_content = "Aku tak tahu bagaimana harus memberitahumu bahwa pujianmu membuatku sangat senang.",
  ui_story_30610601_61_dialog_content = "Nah, sekarang, coba katakan kepadaku… Menurutmu, sekarang kita ada di mana?",
  ui_story_30610601_62_dialog_content = "Sebentar… Ini Tir' Hotel!",
  ui_story_30610601_63_dialog_content = "Menarik… Rupanya pikiranmu mengingat Tir' Hotel, ya?",
  ui_story_30610601_64_dialog_content = "Mungkinkah itu karena kau punya banyak kenangan indah tentang tempat ini?",
  ui_story_30610601_65_dialog_content = "Ya.",
  ui_story_30610601_66_dialog_content = "Ya… Aku bisa merasakannya! Perasaan bahagia yang kuat mulai tumbuh dalam hatiku!",
  ui_story_30610601_67_dialog_content = "Kau membayangkan masa-masa yang kaulewati di sini bersama teman-temanmu… Serta… Permainan voli pantai…",
  ui_story_30610601_68_dialog_content = "… Voli pantai?",
  ui_story_30610601_69_dialog_content = "A-aku tak tahu voli pantai bisa dimainkan seperti ini…",
  ui_story_30610601_70_dialog_content = "SUPER HELLSTORM SPIKE!",
  ui_story_30610601_71_dialog_content = "Wow! Suasananya sangat penuh semangat!",
  ui_story_30610601_72_dialog_content = "Gelombang panas yang mendekat, serta kombinasi antara pasir halus dan angin laut…!",
  ui_story_30610601_73_dialog_content = "Musim panas, teman-teman, dan pantai… Kurasa sekarang aku jadi makin mengenalmu!",
  ui_story_30610601_74_dialog_content = "Hanya saja, aku tak pernah menyangka…",
  ui_story_30610601_75_dialog_content = "Bahwa kau akan merasa \"bahagia\" dengan membayangkan semua gadis itu!!",
  ui_story_30610601_76_dialog_content = "Koresponden perang…? Hmm… Sepertinya pikiranmu mulai berubah…",
  ui_story_30610601_77_dialog_content = "Semua mulai tenang…",
  ui_story_30610601_78_dialog_content = "Pertandingan sudah selesai dan pemenangnya sudah ditetapkan.",
  ui_story_30610601_79_dialog_content = "Bagus, bagus…",
  ui_story_30610601_80_dialog_content = "Nah, pelan-pelan kita mulai bisa mengeluarkan emosi kita…",
  ui_story_30610601_81_dialog_content = "Mari lanjutkan perjalanan.",
  ui_story_30610601_82_dialog_content = "Hmm… Tiupan angin hangat lagi-lagi menerpa wajahku…",
  ui_story_30610601_83_dialog_content = "Kira-kira, sekarang kita ada di mana? Aku yakin kau pasti tahu…",
  ui_story_30610601_84_dialog_content = "Rediesel Desert.",
  ui_story_30610601_85_dialog_content = "Oh? Sepertinya kau juga punya kenangan tak terlupakan di tempat ini.",
  ui_story_30610601_86_dialog_content = "Oh-oh! Sepertinya emosimu mulai bergejolak lagi!",
  ui_story_30610601_87_dialog_content = "Udara yang panas dan terik, debu yang berhamburan, dan perasaan liar penuh kebebasan…",
  ui_story_30610601_88_dialog_content = "Sepertinya kau sedang mengingat… balapan?",
  ui_story_30610601_89_dialog_content = "Ya! Kenangan membara dan penuh semangat seperti ini…",
  ui_story_30610601_90_dialog_content = "Sekarang aku paham!",
  ui_story_30610601_91_dialog_content = "Ternyata kau bukan sekadar penonton di pinggir arena…",
  ui_story_30610601_92_dialog_content = "Rupanya kau sendiri juga ikut terjun dalam balapan ini!",
  ui_story_30610601_93_dialog_content = "Lihat, 'kan? Kau mengemudikan mobil balap luar biasa di sebelah sana!",
  ui_story_30610601_94_dialog_content = "Sungguh pemberani… Walaupun balapannya sangat sengit, kau sama sekali tak gentar!",
  ui_story_30610601_95_dialog_content = "Sepertinya ada beberapa orang yang membicarakan dirimu juga…",
  ui_story_30610601_96_dialog_content = "Oh? Rupanya bocah tengil itu bisa mengemudi seperti seorang pro, ya? Padahal menggunakan Luminatics sebesar ludah Sandworm saja dia tak mampu.",
  ui_story_30610601_97_dialog_content = "Kok mobil mereka bisa secepat itu, sih? Mungkin harusnya kutinggalkan saja mobilku di rumah…",
  ui_story_30610601_98_dialog_content = "Namun, kau tak bisa bilang apa pun kepada mereka… Kau hanya bisa terus melaju…",
  ui_story_30610601_99_dialog_content = "Tak ada yang bisa menghentikanmu atau mobil balapmu!",
  ui_story_30610601_100_dialog_content = "Kau berhasil mencapai garis finis! Posisi pertama!",
  ui_story_30610601_101_dialog_content = "Kaulah jawara gurun ini!",
  ui_story_30610601_102_dialog_content = "Sorak-sorai dan tepuk tangan membahana dari bangku penonton… Mereka menyerukan namamu!",
  ui_story_30610601_103_dialog_content = "PlayerName! PlayerName! PlayerName!",
  ui_story_30610601_104_dialog_content = "Gairah muda yang membara… Semangat ini sungguh luar biasa!",
  ui_story_30610601_105_dialog_content = "Sungguh emosi yang luar biasa kuat!",
  ui_story_30610601_106_dialog_content = "Kau hebat sekali, PlayerName!",
  ui_story_30610601_107_dialog_content = "Nah, sekarang, atur napasmu…",
  ui_story_30610601_108_dialog_content = "Kita kembali melayang di langit dalam balon udara…",
  ui_story_30610601_109_dialog_content = "Kita dikelilingi birunya permukaan laut yang jernih…",
  ui_story_30610601_110_dialog_content = "Desau angin musim panas yang segar… dan deburan ombak di bawah sana…",
  ui_story_30610601_111_dialog_content = "Satu-satunya suara yang kaudengar hanyalah ombak dan angin laut…",
  ui_story_30610601_112_dialog_content = "Pejamkan matamu…",
  ui_story_30610601_113_dialog_content = "Prioritas utamaku adalah menjaga agar kau tetap hidup dan selamat.",
  ui_story_30610601_114_dialog_content = "Di mana ada kemauan, di situ ada jalan.",
  ui_story_30610601_115_dialog_content = "Ini ujian, PlayerName. Kau bisa jadi kuat hanya jika kau bisa mengasah keteguhanmu dalam kesendirian.",
  ui_story_30610601_116_dialog_content = "Sekarang, aku akan memutar rekaman sejarah negeri ini untukmu. Ini akan membantumu untuk lebih memahami dunia yang kita diami ini.",
  ui_story_30610601_117_dialog_content = "Akan kuputar juga rekaman tentang taktik militer… Jangan protes. Tak ada gunanya protes.",
  ui_story_30610601_118_dialog_content = "Semua ini adalah pelajaran yang memang perlu dipahami kalau kau ingin bisa bertahan hidup di dunia luar. Akan tiba hari saat…",
  ui_story_30610601_119_dialog_content = "A-apa ini…?",
  ui_story_30610601_120_dialog_content = "Emosi PlayerName…",
  ui_story_30610601_121_dialog_content = "Nostalgia, rasa takut, kecemasan… Aku harus bisa mengatasi semua itu agar bisa jadi lebih kuat.",
  ui_story_30610601_122_dialog_content = "Kuharap kau bisa belajar untuk mengatasinya… Kau bisa mulai dengan mengucapkan salam perpisahan kepadaku.",
  ui_story_30610601_123_dialog_content = "Kau hanya akan bisa memenuhi takdirmu sebagai seorang Caelestite kalau bisa pergi dari sini. Pergilah, semua orang mengandalkanmu!",
  ui_story_30610601_124_dialog_content = "Dan aku pun tak akan ke mana-mana. Jangan khawatir.",
  ui_story_30610601_125_dialog_content = "Perasaan ketergantungan dan ketenangan… Akan tetapi, ada juga perasaan enggan…",
  ui_story_30610601_126_dialog_content = "Pada akhirnya, emosi PlayerName mulai terasa…",
  ui_story_30610601_127_dialog_content = "Bisa dibilang hangat.",
  ui_story_30610601_128_dialog_content = "Perasaan tenang dalam kesendirian…",
  ui_story_30610601_129_dialog_content = "Apa perasaan seperti ini sungguh bisa membuat kita bahagia?",
  ui_story_30610601_130_dialog_content = "Kau mulai tersenyum…",
  ui_story_30610601_131_dialog_content = "Kurasa sekarang saatnya kau bangun, PlayerName.",
  ui_story_30610601_132_dialog_content = "Oh!",
  ui_story_30610601_133_dialog_content = "Kau sudah sadar?",
  ui_story_30610601_134_dialog_content = "Bagaimana perasaanmu sekarang?",
  ui_story_30610601_135_dialog_content = "Jauh lebih baik…",
  ui_story_30610601_136_dialog_content = "Yang kurasakan sekarang ini… Sulit dijelaskan.",
  ui_story_30610601_137_dialog_content = "Rasanya seakan-akan… Kau membawaku masuk menyelami pikiranku sendiri dan membantuku menemukan kedamaian dalam pikiranku.",
  ui_story_30610601_138_dialog_content = "Bukan sekadar kebahagiaan atau kegembiraan, tapi rasa damai dan tenang yang nyata.",
  ui_story_30610601_139_dialog_content = "Aku juga merasa tak akan mudah terpengaruh lagi oleh emosi negatif karena aku sadar ada sesuatu yang bisa kuandalkan…",
  ui_story_30610601_140_dialog_content = "Rasanya seperti… hubungan yang kuat dan penuh perasaan.",
  ui_story_30610601_141_dialog_content = "Baguslah kalau begitu!",
  ui_story_30610601_142_dialog_content = "Sepertinya latihan berpikir positif untuk hari ini sukses besar!",
  ui_story_30610601_143_dialog_content = "Serius. Aku merasa jauh lebih baik daripada sebelumnya!",
  ui_story_30610601_144_dialog_content = "Berusahalah semampumu untuk mengingat apa yang kaurasakan sekarang ini, ya?",
  ui_story_30610601_145_dialog_content = "Lain kali, jangan lagi mengurung dirimu di kamar!",
  ui_story_30610601_146_dialog_content = "Jangan biarkan dirimu terpenjara oleh emosimu sendiri. Kau harus berani menghadapinya dan berusaha mengatasinya dengan segenap kemampuanmu.",
  ui_story_30610601_147_dialog_content = "Terakhir, kita harus selalu ingat momen-momen dalam hidup yang paling membahagiakan bagi kita.",
  ui_story_30610601_148_dialog_content = "Hanya dengan cara itulah kita bisa menghadapi emosi negatif kita dan bisa memahaminya dengan jelas.",
  ui_story_30610601_149_dialog_content = "Ya… Kau benar sekali.",
  ui_story_30610601_150_dialog_content = "Kau juga merasa lebih lega, 'kan?",
  ui_story_30610601_151_dialog_content = "Ya… Karena sudah berhasil mengatasi pikiran negatif itu, sekarang aku merasa lebih lega dan lebih bersemangat!",
  ui_story_30610601_152_dialog_content = "Kalau begitu, mestinya sekarang kau bisa bersiap untuk menempuh perjalananmu, 'kan?",
  ui_story_30610601_153_dialog_content = "Yap! Begitu aku kembali dari Umbraton, aku janji akan langsung membalas jasamu ini. Jadi, jangan ke mana-mana, ya!",
  ui_story_30610601_154_dialog_content = "Terima kasih, tapi tak usah repot-repot.",
  ui_story_30610601_155_dialog_content = "Fyuh… Untunglah tak ada masalah dengan latihannya.",
  ui_story_30610601_156_dialog_content = "Bisa-bisanya sih aku berbuat bodoh begitu? Keliru memutar rekaman…",
  ui_story_30610601_157_dialog_content = "Jangan-jangan, aku sendiri juga kelelahan?",
  ui_story_30610601_158_dialog_content = "Balon udara, ya? Lumayan juga untuk dibayangkan agar merasa rileks…",
  ui_story_30610601_159_dialog_content = "Mungkin kapan-kapan sebaiknya aku beli setelan komentator dan bertamasya naik balon udara?",
  ui_story_30610601_160_dialog_content = "Benar.",
  ui_story_30610601_161_dialog_content = "Pertama-tama, aku harus minta cuti dulu kepada Gronru…"
}
